<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #121212;
    color: #eeeeee;
    font-family: Arial, Helvetica, sans-serif;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 24px;
  }
  h1 {
    font-size: 48px;
    margin-bottom: 16px;
    color: #edc22e;
    letter-spacing: 2px;
  }
  .topbar {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 16px;
  }
  .score-box {
    background: #1e1e1e;
    border: 1px solid #333;
    border-radius: 8px;
    padding: 8px 18px;
    text-align: center;
    min-width: 110px;
  }
  .score-box .label {
    display: block;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #999;
  }
  #score {
    display: block;
    font-size: 26px;
    font-weight: bold;
    color: #ffffff;
  }
  #reset {
    background: #edc22e;
    color: #1a1a1a;
    border: none;
    border-radius: 8px;
    padding: 12px 20px;
    font-size: 16px;
    font-weight: bold;
    cursor: pointer;
  }
  #reset:hover { background: #f5d45c; }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 92px);
    grid-template-rows: repeat(4, 92px);
    gap: 10px;
    background: #1e1e1e;
    border: 1px solid #333;
    padding: 10px;
    border-radius: 12px;
  }
  .cell {
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    background: #2b2b2b;
    color: #f9f6f2;
    font-size: 34px;
    font-weight: bold;
    user-select: none;
  }
  .cell.v2    { background: #eee4da; color: #776e65; }
  .cell.v4    { background: #ede0c8; color: #776e65; }
  .cell.v8    { background: #f2b179; }
  .cell.v16   { background: #f59563; }
  .cell.v32   { background: #f67c5f; }
  .cell.v64   { background: #f65e3b; }
  .cell.v128  { background: #edcf72; font-size: 30px; }
  .cell.v256  { background: #edcc61; font-size: 30px; }
  .cell.v512  { background: #edc850; font-size: 30px; }
  .cell.v1024 { background: #edc53f; font-size: 24px; }
  .cell.v2048 { background: #edc22e; font-size: 24px; }
  .cell.vbig  { background: #3c3a32; font-size: 22px; }
  .hint {
    margin-top: 16px;
    color: #888;
    font-size: 14px;
  }
</style>
</head>
<body>
  <h1>2048</h1>
  <div class="topbar">
    <div class="score-box">
      <span class="label">Score</span>
      <span id="score">0</span>
    </div>
    <button id="reset">New Game</button>
  </div>
  <div id="board"></div>
  <div class="hint">Use the arrow keys to slide and merge tiles.</div>

<script>
(function () {
  'use strict';

  var SIZE = 4;
  var grid = [];
  var scoreVal = 0;

  var boardEl = document.getElementById('board');
  var scoreEl = document.getElementById('score');
  var resetBtn = document.getElementById('reset');

  // Build the 16 cell elements once.
  var cells = [];
  for (var i = 0; i < SIZE * SIZE; i++) {
    var d = document.createElement('div');
    d.className = 'cell';
    boardEl.appendChild(d);
    cells.push(d);
  }

  function emptyGrid() {
    var g = [];
    for (var r = 0; r < SIZE; r++) {
      var row = [];
      for (var c = 0; c < SIZE; c++) row.push(0);
      g.push(row);
    }
    return g;
  }

  function render() {
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = grid[r][c];
        var cell = cells[r * SIZE + c];
        cell.textContent = v === 0 ? '' : String(v);
        var cls = 'cell';
        if (v !== 0) cls += (v <= 2048) ? (' v' + v) : ' vbig';
        cell.className = cls;
      }
    }
    scoreEl.textContent = String(scoreVal);
  }

  function spawn() {
    var empties = [];
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        if (grid[r][c] === 0) empties.push([r, c]);
      }
    }
    if (empties.length === 0) return;
    var pos = empties[Math.floor(Math.random() * empties.length)];
    grid[pos[0]][pos[1]] = Math.random() < 0.9 ? 2 : 4;
  }

  function reset() {
    grid = emptyGrid();
    scoreVal = 0;
    spawn();
    spawn();
    render();
  }

  // Slide+merge a single line toward index 0. Each tile merges at most once.
  function mergeLine(line) {
    var vals = [];
    for (var i = 0; i < line.length; i++) {
      if (line[i] !== 0) vals.push(line[i]);
    }
    var out = [];
    var gained = 0;
    for (var j = 0; j < vals.length; j++) {
      if (j + 1 < vals.length && vals[j] === vals[j + 1]) {
        var merged = vals[j] * 2;
        out.push(merged);
        gained += merged;
        j++; // skip the consumed tile: no double merges
      } else {
        out.push(vals[j]);
      }
    }
    while (out.length < SIZE) out.push(0);
    return { line: out, gained: gained };
  }

  function move(dir) {
    if (dir !== 'left' && dir !== 'right' && dir !== 'up' && dir !== 'down') {
      return false;
    }

    var before = grid.map(function (row) { return row.slice(); });
    var next = emptyGrid();
    var gained = 0;

    if (dir === 'left' || dir === 'right') {
      for (var r = 0; r < SIZE; r++) {
        var line = grid[r].slice();
        if (dir === 'right') line.reverse();
        var res = mergeLine(line);
        var out = res.line;
        if (dir === 'right') out = out.slice().reverse();
        next[r] = out;
        gained += res.gained;
      }
    } else { // up / down
      for (var c = 0; c < SIZE; c++) {
        var col = [];
        for (var r2 = 0; r2 < SIZE; r2++) col.push(grid[r2][c]);
        if (dir === 'down') col.reverse();
        var res2 = mergeLine(col);
        var out2 = res2.line;
        if (dir === 'down') out2 = out2.slice().reverse();
        for (var r3 = 0; r3 < SIZE; r3++) next[r3][c] = out2[r3];
        gained += res2.gained;
      }
    }

    var changed = false;
    for (var r4 = 0; r4 < SIZE && !changed; r4++) {
      for (var c4 = 0; c4 < SIZE; c4++) {
        if (before[r4][c4] !== next[r4][c4]) { changed = true; break; }
      }
    }

    if (!changed) return false;

    grid = next;
    scoreVal += gained;
    spawn();
    render();
    return true;
  }

  function board() {
    return grid.map(function (row) { return row.slice(); });
  }

  function setBoard(arr) {
    grid = emptyGrid();
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = 0;
        if (arr && arr[r] && typeof arr[r][c] === 'number' && isFinite(arr[r][c])) {
          v = arr[r][c];
        }
        grid[r][c] = v;
      }
    }
    render();
  }

  function score() {
    return scoreVal;
  }

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: board,
    setBoard: setBoard,
    score: score
  };

  document.addEventListener('keydown', function (e) {
    var map = {
      ArrowLeft: 'left',
      ArrowRight: 'right',
      ArrowUp: 'up',
      ArrowDown: 'down'
    };
    var dir = map[e.key];
    if (dir) {
      e.preventDefault();
      move(dir);
    }
  });

  resetBtn.addEventListener('click', function () {
    reset();
    resetBtn.blur();
  });

  reset();
})();
</script>
</body>
</html>
